package io.neo.omnitrix;

import android.app.*;import android.content.*;import android.graphics.Color;import android.os.Bundle;import android.view.*;import android.widget.*;import java.text.DateFormat;import java.util.*;

/** Omnitrix Suit v3.5 integration layer: global command, shared recents, cloud hub, and cross-app routing. */
public class SuiteIntegrationActivity extends Activity {
 private EditText command; private TextView recent; private SharedPreferences prefs;
 @Override public void onCreate(Bundle s){super.onCreate(s);getWindow().setStatusBarColor(Color.BLACK);getWindow().setNavigationBarColor(Color.BLACK);prefs=getSharedPreferences("omnitrix.integration",MODE_PRIVATE);build();}
 private void build(){LinearLayout shell=new LinearLayout(this);shell.setOrientation(LinearLayout.VERTICAL);shell.setBackgroundColor(Color.rgb(1,5,3));ScrollView scroll=new ScrollView(this);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(18),dp(20),dp(18),dp(24));scroll.addView(root);LinearLayout head=new LinearLayout(this);head.setGravity(Gravity.CENTER_VERTICAL);ImageView logo=new ImageView(this);logo.setImageResource(R.drawable.omnitrix_logo);head.addView(logo,new LinearLayout.LayoutParams(dp(62),dp(62)));LinearLayout words=new LinearLayout(this);words.setOrientation(LinearLayout.VERTICAL);words.addView(text("OMNITRIX COMMAND",23,Color.rgb(229,255,236)));words.addView(text("NEO-0001 · Suite Integration v3.5",12,Color.rgb(104,185,130)));head.addView(words);root.addView(head);TextView sub=text("Search, launch apps, route files, and manage shared local-first suite state from one surface.",12,Color.rgb(184,218,194));sub.setPadding(0,dp(8),0,dp(14));root.addView(sub);command=new EditText(this);command.setHint("Try: wallet, docs, cloud, maps, news, miner, or search terms");command.setSingleLine(true);command.setTextColor(Color.WHITE);command.setHintTextColor(Color.rgb(96,130,108));command.setBackgroundColor(Color.rgb(5,20,12));command.setPadding(dp(12),0,dp(12),0);root.addView(command,new LinearLayout.LayoutParams(-1,dp(54)));Button go=primary("RUN COMMAND");LinearLayout.LayoutParams gp=new LinearLayout.LayoutParams(-1,dp(50));gp.setMargins(0,dp(8),0,0);root.addView(go,gp);go.setOnClickListener(v->run(command.getText().toString().trim()));TextView h=text("RECENT SUITE ACTIVITY",13,Color.rgb(119,255,151));h.setPadding(0,dp(22),0,dp(8));root.addView(h);recent=text(prefs.getString("recent","No recent cross-app activity yet."),12,Color.rgb(192,226,201));recent.setTextIsSelectable(true);root.addView(recent);Button cloud=secondary("OPEN NEO CLOUD + SYNC");LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,dp(48));cp.setMargins(0,dp(16),0,0);root.addView(cloud,cp);cloud.setOnClickListener(v->launch(NeoCloudHubActivity.class,"Opened NEO Cloud + Sync"));Button settings=secondary("OPEN NEO ACCOUNT / SETTINGS");LinearLayout.LayoutParams pp=new LinearLayout.LayoutParams(-1,dp(48));pp.setMargins(0,dp(8),0,0);root.addView(settings,pp);settings.setOnClickListener(v->launch(ConsumerHomeActivity.class,"Opened NEO profile settings"));Button files=secondary("ROUTE FILE / MEDIA");LinearLayout.LayoutParams fp=new LinearLayout.LayoutParams(-1,dp(48));fp.setMargins(0,dp(8),0,0);root.addView(files,fp);files.setOnClickListener(v->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("*/*");startActivityForResult(i,44);record("Opened shared file/media picker");});Button suite=secondary("OPEN FULL OMNITRIX SUIT");LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(-1,dp(48));sp.setMargins(0,dp(8),0,0);root.addView(suite,sp);suite.setOnClickListener(v->launch(SuiteLauncherActivity.class,"Opened full suite launcher"));shell.addView(scroll,new LinearLayout.LayoutParams(-1,0,1f));shell.addView(OmnitrixNav.bar(this,"NEO"),new LinearLayout.LayoutParams(-1,dp(54)));setContentView(shell);}
 private void run(String q){if(q.isEmpty())return;String s=q.toLowerCase(Locale.US);if(s.contains("wallet")||s.contains("pay"))launch(WalletDashboardActivity.class,"Opened Wallet");else if(s.contains("market")||s.contains("finance"))launch(MarketMatrixActivity.class,"Opened Market Matrix");else if(s.contains("miner"))launch(MinerControlActivity.class,"Opened Miner Control");else if(s.contains("cloud")||s.contains("sync")||s.contains("recent")||s.contains("favorite"))launch(NeoCloudHubActivity.class,"Opened NEO Cloud + Sync");else if(s.contains("browser")||s.startsWith("http"))launch(MainActivityV14.class,"Opened Browser");else if(s.contains("docs"))openWave("noogle-docs","Noogle Docs");else if(s.contains("sheet"))openWave("noogle-sheets","Noogle Sheets");else if(s.contains("slide"))openWave("noogle-slides","Noogle Slides");else if(s.contains("keep")||s.contains("note"))openWave("noogle-keep","Noogle Keep");else if(s.contains("mail"))openWave("neomail","Neomail");else if(s.contains("calendar"))openWave("noogle-calendar","Noogle Calendar");else if(s.contains("maps"))openWave("noogle-maps","Noogle Maps");else if(s.contains("news"))openWave("noogle-news","Noogle News");else {Intent i=new Intent(this,MainActivityV14.class);i.putExtra("search_query",q);startActivity(i);record("Noogle search: "+q);}}
 private void openWave(String id,String name){Intent i=new Intent(this,SuiteWave1Activity.class);i.putExtra(SuiteWave1Activity.EXTRA_ID,id);i.putExtra(SuiteWave1Activity.EXTRA_NAME,name);startActivity(i);record("Opened "+name);}
 private void launch(Class<?> c,String event){startActivity(new Intent(this,c));record(event);} private void record(String event){String now=DateFormat.getDateTimeInstance(DateFormat.SHORT,DateFormat.SHORT).format(new Date());String old=prefs.getString("recent","");String next="• "+now+" — "+event+(old.isEmpty()?"":"\n"+old);String[] lines=next.split("\n");StringBuilder b=new StringBuilder();for(int i=0;i<Math.min(lines.length,12);i++){if(i>0)b.append("\n");b.append(lines[i]);}prefs.edit().putString("recent",b.toString()).apply();SuiteSyncBus.recent(this,"Omnitrix Command",event,"command://"+event.hashCode());if(recent!=null)recent.setText(b.toString());}
 @Override protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r==44&&c==RESULT_OK&&d!=null&&d.getData()!=null){Intent share=new Intent(Intent.ACTION_SEND);share.setType(getContentResolver().getType(d.getData())==null?"*/*":getContentResolver().getType(d.getData()));share.putExtra(Intent.EXTRA_STREAM,d.getData());share.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(Intent.createChooser(share,"Open in / share with…"));SuiteSyncBus.recent(this,"Files",d.getData().toString(),d.getData().toString());SuiteSyncBus.queueSync(this,"Files","Shared file metadata",d.getData().toString());record("Routed a file/media item across apps");}}
 private TextView text(String s,float z,int c){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(c);return t;}private Button primary(String s){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextColor(Color.rgb(0,22,8));b.setBackgroundColor(Color.rgb(101,255,138));return b;}private Button secondary(String s){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextColor(Color.rgb(188,235,201));b.setBackgroundColor(Color.rgb(7,25,15));return b;}private int dp(int v){return(int)(v*getResources().getDisplayMetrics().density+.5f);}
}
